#!/bin/sh
set -eu
ROOT=$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)
rm -rf "$ROOT/web/dist"
mkdir -p "$ROOT/web/dist"
cp -R "$ROOT/../client/dist/." "$ROOT/web/dist/"

# Seed static game data generated by the legacy data scripts. Account-specific
# files (operbox.json, depot.json, run stores) are never seeded.
SEED_DIR="$ROOT/resources/seed"
if [ -d "$ROOT/../server/data" ]; then
  mkdir -p "$SEED_DIR"
  for f in operator-mastery.json operator-materials.json stages.json paradox-operators.json; do
    if [ -f "$ROOT/../server/data/$f" ]; then
      cp "$ROOT/../server/data/$f" "$SEED_DIR/$f"
    fi
  done
fi
